136	/*
137	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
138	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
139	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
140	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
141	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
142	 *
143	 * Substituting them is a follow-up rather than part of this PR only because it also removes
144	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
145	 * across every commit.
146	 */
147	type SfccProduct = any;
148	type SfccVariant = any;
149	type SfccCategory = any;
150	type SfccPriceData = any;
151	
152	/** One selectable value of a variation attribute, as the base hooks shape it. */
153	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
154	
155	/** A variation attribute (colour, size, ...) with its selectable values. */
156	type SfccVariationAttribute = {
157	  id: string;
158	  name?: string;
159	  selectedValue?: SfccVariationValue;
160	  values: SfccVariationValue[];
161	};
162	
163	/** SFCC variation attribute ID for the colour attribute. */
164	export const SFCC_COLOUR_ATTRIBUTE_ID = 'color';
165	
166	/** SFCC variation attribute ID for the size attribute. */
167	export const SFCC_SIZE_ATTRIBUTE_ID = 'size';
168	
169	/** The per-child orderability record ProductView writes back to its parent. */
170	export type ChildProductOrderability = {
171	  showInventoryMessage?: boolean;
172	  unfulfillable?: boolean;
173	  isOutOfStock?: boolean;
174	  stockLevel?: number;
175	  productName?: string;
176	};
177	
178	export type ProductViewHeaderProps = {
179	  name?: string;
180	  currency?: string;
181	  priceData?: SfccPriceData;
182	  category?: SfccCategory[];
183	  product?: SfccProduct;
184	  isProductPartOfBundle?: boolean;
185	  /**
186	   * The wishlist toggle badge (SFCC-434), built by `ProductView` itself since it needs
187	   * internal state (`variant`, `hasSizeAttribute`, `sizeSelectorRef`) the caller does not have.
188	   * `undefined` for any caller that does not wire wishlist props at all. Threaded into the
189	   * default `ProductViewHeader` fallback too, so every caller (PDP, cart, quick-view,
190	   * bonus-product) gets it uniformly — there is no separate CTA-column wishlist button anymore.
191	   */
192	  wishlistButton?: React.ReactNode;
193	};
194	
195	/*
196	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
197	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
198	 * from the default implementation the base file supplies.
199	 */
200	type ProductViewProps = {
201	  product?: SfccProduct;
202	  category?: SfccCategory[];
203	  showFullLink?: boolean;
204	  imageSize?: 'sm' | 'md';
205	  isWishlistLoading?: boolean;
206	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
207	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
208	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
209	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
210	  /**
211	   * Removes the current variant from the wishlist (SFCC-434, AC4) — the toggle-off half of
212	   * `addToWishlist`. Distinct from `updateWishlist` above, which base SFCC uses for a
213	   * different (already-in-basket quantity update) semantic this codebase never wires up.
214	   */
215	  removeFromWishlist?: ((product: SfccProduct, variant: SfccVariant) => unknown) | null;
216	  /**
217	   * List-item productIds currently in the customer's wishlist (SFCC-434). A plain array, not
218	   * a derived `isInWishlist` boolean: the currently selected size/variant lives inside this
219	   * component (`effectiveSizeValue`/`localSizeValue` below), not in the container, so only
220	   * `ProductView` itself can compute the variant-scoped result reactively — same reasoning as
221	   * `basketProductItems` further down for `isMaxOrderQtyReached`.
222	   */
223	  wishlistedProductIds?: ReadonlyArray<string>;
224	  /**
225	   * True while the wishlist add/remove mutation itself is in flight (SFCC-434) — distinct from
226	   * `isWishlistLoading` above, which reflects the wishlist *query's* loading state, not the
227	   * mutation's. Guards the new header badge against a double-fire mid-mutation; the existing
228	   * CTA-column wishlist button's own disabled check is untouched.
229	   */
230	  isWishlistMutating?: boolean;
231	  isProductLoading?: boolean;
232	  isProductPartOfSet?: boolean;
233	  isProductPartOfBundle?: boolean;
234	  childOfBundleQuantity?: number;
235	  childProductOrderability?: Record<string, ChildProductOrderability>;
236	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
237	  isBasketLoading?: boolean;
238	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
239	  validateOrderability?: (
240	    variant: SfccVariant,
241	    product: SfccProduct,
242	    quantity: number,
243	    stockLevel: number,
244	  ) => boolean | undefined;
245	  showImageGallery?: boolean;
246	  setSelectedBundleQuantity?: (quantity: number) => void;
247	  selectedBundleParentQuantity?: number;
248	  pickupInStore?: boolean;
249	  setPickupInStore?: (checked: boolean) => void;
250	  onOpenStoreLocator?: () => void;
251	  showDeliveryOptions?: boolean;
252	  customButtons?: React.ReactElement[];
253	  promotionId?: string;
254	  maxOrderQuantity?: number | null;
255	  /**
256	   * Basket line items from the current session, used to enforce `maxOrderQuantity`
257	   * per size variant (SFCC-196). Passed in from the PDP page; components under
258	   * `overrides/app/components/` must not call data-fetching hooks directly.
259	   */
260	  basketProductItems?: ReadonlyArray<{ productId?: string; quantity?: number }>;
261	  imageGalleryFooter?: React.ReactNode;
262	  alignItems?: string;
263	  controlledVariationValues?: Record<string, string> | null;
264	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
265	  /**
266	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
267	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
268	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
269	   * them. Defaults to rendering that same private header, so every existing caller — cart,
270	   * wishlist, bonus-product — is byte-identical unless it opts in.
271	   *
272	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
273	   * twice with the same arguments. Keep it pure.
274	   */
275	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
276	  /**
277	   * Render slot for overriding how a single variation attribute is displayed. When provided,
278	   * the returned node replaces the base SwatchGroup for that attribute. Return `undefined` (or
279	   * omit the prop) to fall through to `renderDefaultVariationAttribute` — the base SwatchGroup
280	   * rendering. The PDP uses this to inject `ZimmColourSwatchGroup` for the colour attribute;
281	   * the quick-view modal omits it and keeps the base SwatchGroup for all attributes.
282	   */
283	  renderVariationAttribute?: (attr: SfccVariationAttribute) => React.ReactNode;
284	  /**
285	   * The second Zimmermann addition to this component's prop surface (SFCC-736/195). Renders
286	   * after the CTAs (`renderActionButtons()`), inside the same column — Figma's "Find in
287	   * Boutique" link and the Details & Care / Size Guide / Shipping & Returns / Assistance
288	   * drawer-trigger rows. A plain node, like the existing `imageGalleryFooter` slot, not a
289	   * render-prop like `renderHeader`: this content needs none of ProductView's own render-time
290	   * data, it is driven entirely by state the caller (`product-detail/index.tsx`) already owns.
291	   * `null` by default, so every existing caller (cart, wishlist, bonus-product) is unaffected.
292	   */
293	  footerLinks?: React.ReactNode;
294	  /**
295	   * Set to `false` to hide the quantity picker. Defaults to `true` so every existing caller
296	   * (wishlist, cart, bonus-product) is unaffected. The PDP passes `false` because quantity
297	   * selection is not part of the Zimmermann PDP design.
298	   */
299	  showQuantityPicker?: boolean;
300	  /**
301	   * Set to `false` to suppress the SFCC-native inventory/stock message (e.g. "Out of stock")
302	   * that appears below Add to Bag. Defaults to `true`. The PDP passes `false` because OOS state
303	   * is communicated through the size selector dropdown items and the aria-disabled button state.
304	   */
305	  showStockMessage?: boolean;
306	  /**
307	   * Set to `false` to hide the desktop action-buttons column and the sticky mobile CTA bar.
308	   * Defaults to `true`. The PDP passes `false` because Add to Bag is rendered inline with the
309	   * size selector and Add to Wishlist lives in the product header, making these bars redundant.
310	   */
311	  showActionButtons?: boolean;
312	  /** Called when the user clicks the "Find Your Size" link beside the size selector. */
313	  onFindYourSizeClick?: () => void;
314	  /** Called when the user clicks the "Size Guide" inside the size selector. */
315	  onSizeGuideClick?: () => void;
316	};
317	
318	/*
319	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
320	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
321	 * pages/product-detail).
322	 */
323	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
324	
325	/**
326	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
327	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
328	 * below. A consumer names it as the `this` parameter of its ref callback —
329	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
330	 * as written; no assertion is required at the prop site.
331	 */
332	export type ProductViewRefScope = {
333	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
334	};
335	
336	const ProductViewHeader = ({
337	  name,
338	  currency,
339	  priceData,
340	  category,
341	  product,
342	  isProductPartOfBundle,
343	  wishlistButton,
344	}: ProductViewHeaderProps) => {
345	  return (
346	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
347	      {category && (
348	        <Skeleton isLoaded={category} minWidth={64}>
349	          <Breadcrumb categories={category} />
350	        </Skeleton>
351	      )}
352	
353	      {/* Title row — name on the left, optional wishlist button on the right */}
354	      <Flex justify="space-between" align="flex-start" width="100%">
355	        <Skeleton isLoaded={name}>
356	          <Heading fontSize="2xl">{`${name}`}</Heading>
357	        </Skeleton>
358	        {wishlistButton}
359	      </Flex>
360	
361	      {!isProductPartOfBundle && (
362	        <>
363	          <Skeleton isLoaded={priceData?.currentPrice}>
364	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
365	          </Skeleton>
366	
367	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
368	        </>
369	      )}
370	    </VStack>
371	  );
372	};
373	
374	/**
375	 * Render a product detail view that includes name, image gallery, price,
376	 * variant selections, action buttons
377	 */
378	
379	const ProductView = forwardRef(
380	  (
381	    {
382	      product,
383	      category,
384	      showFullLink = false,
385	      // SFCC-731 review finding (CodeRabbit, 2026-09-02): ZimmProductGallery has no
386	      // size-variant concept, so this was briefly a no-op — a real regression for the
387	      // unmodified base callers that pass imageSize="sm" (product-view-modal's quick-view and
388	      // bundle paths, bonus-product-view-modal), whose compact-modal gallery would otherwise
389	      // have silently switched to the full PDP gallery. Fixed by branching on it below: 'sm'
390	      // keeps the base ImageGallery exactly as before, ZimmProductGallery only renders for the
391	      // PDP's own 'md' (default) path.
392	      imageSize = 'md',
393	      isWishlistLoading = false,
394	      addToCart,
395	      updateCart,
396	      addToWishlist,
397	      removeFromWishlist,
398	      wishlistedProductIds = [],
399	      isWishlistMutating = false,
400	      isProductLoading,
401	      isProductPartOfSet = false,
402	      isProductPartOfBundle = false,
403	      childOfBundleQuantity = 0,
404	      childProductOrderability,
405	      setChildProductOrderability,
406	      isBasketLoading = false,
407	      onVariantSelected = () => {},
408	      validateOrderability = (variant, product, quantity, stockLevel) => {
409	        if (isProductLoading) return false;
410	
411	        // If product has variations, a variant must be selected
412	        if (product?.variationAttributes?.length > 0 && !variant) {
413	          return false;
414	        }
415	
416	        // Check if product (either variant or standard) is orderable and if quantity is valid
417	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
418	      },
419	      showImageGallery = true,
420	      setSelectedBundleQuantity = () => {},
421	      selectedBundleParentQuantity = 1,
422	      pickupInStore = false,
423	      setPickupInStore = () => {},
424	      onOpenStoreLocator = () => {},
425	      showDeliveryOptions = true,
426	      customButtons = [],
427	      maxOrderQuantity = null,
428	      basketProductItems = [],
429	      imageGalleryFooter = null,
430	      controlledVariationValues = null,
431	      onVariationChange = null,
432	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
433	      renderVariationAttribute,
434	      footerLinks = null,
435	      showQuantityPicker = true,
436	      showStockMessage = true,
437	      showActionButtons = true,
438	      onFindYourSizeClick,
439	      onSizeGuideClick,
440	    }: ProductViewProps,
441	    ref: ProductViewRef,
442	  ) => {
443	    const { currency: activeCurrency } = useCurrency();
444	    const showToast = useToast();
445	    const intl = useIntl();
446	    const buildHref = useSafeHref();
447	    const location = useLocation();
448	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
449	    // SFCC-315 (plan step 9) — opens the cart drawer in place of base's AddToCartModal (which
450	    // this file's own base precedent never actually rendered anywhere — see useCartDrawer.ts's
451	    // own module docblock, constraint 1). No "item added" payload: the drawer always renders the
452	    // live basket.
453	    const { isOpen: isCartDrawerOpen, onOpen: onCartDrawerOpen, onClose: onCartDrawerClose } = useCartDrawer();
454	
455	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
456	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
457	
458	    const theme = useTheme();
459	    const { confirmingBasket } = useSFPayments();
460	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
461	
462	    // Tracks the size the shopper picked in the dropdown. product-detail does not pass
463	    // controlledVariationValues for standard products — colour uses URL navigation, but
464	    // size must not change the URL (product-detail computes colour swatch hrefs itself so
465	    // they remain valid even while useDerivedProduct is in controlled mode).
466	    const [localSizeValue, setLocalSizeValue] = useState<string | null>(null);
467	    const urlParams = new URLSearchParams(location.search);
468	    const effectiveControlledVariationValues =
469	      controlledVariationValues !== null
470	        ? controlledVariationValues
471	        : localSizeValue !== null
472	        ? {
473	            ...Object.fromEntries(
474	              (product?.variationAttributes ?? [])
475	                .filter((a: SfccVariationAttribute) => urlParams.has(a.id))
476	                .map((a: SfccVariationAttribute) => [a.id, urlParams.get(a.id) as string]),
477	            ),
478	            size: localSizeValue,
479	          }
480	        : null;
481	    const effectiveSizeValue = effectiveControlledVariationValues?.size ?? null;
482	
483	    const {
484	      showLoading,
485	      showInventoryMessage,
486	      inventoryMessage,
487	      quantity,
488	      minOrderQuantity,
489	      setQuantity,
490	      variant,
491	      variationParams,
492	      variationAttributes,
493	      stockLevel,
494	      stepQuantity,
495	      isOutOfStock,
496	      unfulfillable,
497	      isSelectedStoreOutOfStock,
498	      selectedStore,
499	    } = useDerivedProduct(
500	      product,
501	      isProductPartOfSet,
502	      isProductPartOfBundle,
503	      pickupInStore,
504	      effectiveControlledVariationValues,
505	      onVariationChange,
506	    );
507	    const priceData = useMemo(() => {
508	      return getPriceData(product, { quantity });
509	    }, [product, quantity]);
