         * gallery on mobile/tablet. SFCC-731 scopes this to imageSize="sm" callers only
         * (product-view-modal's quick-view/bundle paths, bonus-product-view-modal), which keep
         * this exactly as the base file always has it. The PDP's own path (imageSize="md", the
         * default) never shows this block — the confirmed Figma compact frames put the gallery
         * unambiguously first, with no header content ahead of it at any breakpoint; the PDP's
         * own header instead always renders after the gallery (see the content column's own
         * `display` below, mirroring this same imageSize condition).
         */}
        {imageSize === 'sm' && (
          <Box display={['block', 'block', 'block', 'none']}>
            {renderHeader({
              name: product?.name,
              product,
              priceData,
              currency: product?.currency || activeCurrency,
              category,
              isProductPartOfBundle,
