/*
 * Tests for the Zimmermann-added contract in product-view/index.tsx.
 *
 * Covers:
 *   - ZimmSizeSelector render (present / absent based on variationAttributes)
 *   - showActionButtons=false suppressing the Add to Bag button when no size attr is present
 *   - isSelectedSizeOOS → ariaDisabled on the inline ZimmButton
 *   - handleAddToBag → setHasAddToBagError → showError on ZimmSizeSelector
 *
 * Architecture note on showActionButtons vs the inline ZimmButton:
 *   showActionButtons=false suppresses the sticky-mobile CTA bar and the desktop
 *   renderActionButtons() box. It does NOT suppress the ZimmSizeSelector or the ZimmButton
 *   rendered inline inside the variationAttributes.map() size branch. That inline pair is
 *   the Add-to-Bag the PDP uses (showActionButtons=false is the PDP flag). Tests that
 *   exercise the inline button therefore pass showActionButtons={false} to prevent the
 *   sticky bar from adding a second data-testid="zimm-add-to-bag" match.
 */

import React from 'react';
