describe('ProductView — Zimmermann additions', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockDerivedProduct();
    // SFCC-315 — fresh default before every test, mirroring mockDerivedProduct()'s own reset;
    // the SFCC-315 suite further down overrides this per-test to capture onOpen.
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: vi.fn(),
      onClose: vi.fn(),
      triggerRef: { current: null },
    });
  });

  test('renders ZimmSizeSelector when useDerivedProduct returns a size variation attribute', () => {
    // Arrange
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    // Act
    render(<ProductView product={buildProductWithSize()} addToCart={vi.fn()} {...quietProps} />);

    // Assert — ZimmSizeSelector appears in the size attribute branch of variationAttributes.map()
    expect(screen.getByTestId('zimm-size-selector')).toBeInTheDocument();
  });

  test('does not render ZimmSizeSelector when variationAttributes has no size entry', () => {
    // Arrange — variationAttributes defaults to [] in mockDerivedProduct
    render(
      <ProductView
        product={{
          id: 'plain',
          name: 'Plain Product',
          type: { item: true },
          inventory: { orderable: true },
          variationAttributes: [],
          imageGroups: [],
        }}
        addToCart={vi.fn()}
        {...quietProps}
      />,
    );

    // Assert
    expect(screen.queryByTestId('zimm-size-selector')).not.toBeInTheDocument();
  });

  test('showActionButtons=false suppresses Add to Bag when there is no size attribute', () => {
    // When there is no size attribute, the only path that renders a ZimmButton is
    // renderActionButtons(), which is called from the desktop box and the sticky mobile
    // bar — both gated by showActionButtons. With showActionButtons=false, neither fires.
    render(
      <ProductView
        product={{
          id: 'plain',
          name: 'Plain Product',
          type: { item: true },
          inventory: { orderable: true },
          variationAttributes: [],
          imageGroups: [],
        }}
        addToCart={vi.fn()}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.queryByTestId('zimm-add-to-bag')).not.toBeInTheDocument();
  });

  test('inline ZimmButton receives aria-disabled="true" when the selected size is OOS', () => {
    // Arrange
    // isSelectedSizeOOS reads product.variationAttributes (L is orderable:false) and
    // effectiveSizeValue. controlledVariationValues forces effectiveSizeValue to 'L'.
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    // Act
    // showActionButtons=false ensures only the inline ZimmButton (from the size block)
    // renders — the sticky mobile bar is suppressed, so getByTestId finds exactly one match.
    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        controlledVariationValues={{ size: 'L' }}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    // Assert
    const button = screen.getByTestId('zimm-add-to-bag');
    expect(button).toHaveAttribute('aria-disabled', 'true');
  });

  test('sets aria-disabled and shows max-qty message when basket already holds the max', () => {
    // Arrange
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={2}
        basketProductItems={[{ productId: 'sku-s', quantity: 2 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    const button = screen.getByTestId('zimm-add-to-bag');
    expect(button).toHaveAttribute('aria-disabled', 'true');
    const sizeSelector = screen.getByTestId('zimm-size-selector');
    expect(sizeSelector).toHaveAttribute('data-show-error', 'true');
    expect(sizeSelector).toHaveAttribute('data-error-message', 'Maximum purchase quantity reached for this size');
  });

  test('does not restrict Add to Bag when a different size variant has reached max', () => {
    // Arrange — basket has 2 of sku-m, selected size is sku-s (AC #3)
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={2}
        basketProductItems={[{ productId: 'sku-m', quantity: 2 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.getByTestId('zimm-add-to-bag')).not.toHaveAttribute('aria-disabled', 'true');
    const sizeSelector = screen.getByTestId('zimm-size-selector');
    expect(sizeSelector).not.toHaveAttribute('data-error-message', 'Maximum purchase quantity reached for this size');
  });

  test('does not restrict Add to Bag when maxOrderQuantity is null', () => {
    // Arrange — no max configured; basket qty irrelevant (AC #4)
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={null}
        basketProductItems={[{ productId: 'sku-s', quantity: 99 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.getByTestId('zimm-add-to-bag')).not.toHaveAttribute('aria-disabled', 'true');
    const sizeSelector = screen.getByTestId('zimm-size-selector');
    expect(sizeSelector).not.toHaveAttribute('data-error-message', 'Maximum purchase quantity reached for this size');
  });

  test('does not show max-qty message when basket qty is below the max', () => {
    mockDerivedProduct({
      variationAttributes: [derivedSizeAttr],
      variant: { productId: 'sku-s' },
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        maxOrderQuantity={3}
        basketProductItems={[{ productId: 'sku-s', quantity: 1 }]}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    expect(screen.getByTestId('zimm-size-selector')).not.toHaveAttribute(
      'data-error-message',
      'Maximum purchase quantity reached for this size',
    );
  });

  test('shows colour prompt (not size error) when colour is missing but size is already selected', async () => {
    // Arrange — both colour and size attrs present; colour NOT in variationParams (none selected).
    mockDerivedProduct({
      variationAttributes: [derivedColourAttr, derivedSizeAttr],
      variationParams: { size: '6' }, // colour absent → isColourMissing=true
      variant: null, // no complete variant without colour → validateOrderability returns false
    });

    render(
      <ProductView
        product={buildProductWithSize()}
        addToCart={vi.fn()}
        controlledVariationValues={{ size: '6' }}
        showActionButtons={false}
        {...quietProps}
      />,
    );

    await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

    // Size selector must NOT show its error — colour is missing, not size.
    expect(screen.getByTestId('zimm-size-selector')).toHaveAttribute('data-show-error', 'false');
    // Colour prompt must appear.
    expect(screen.getByText('Please select a colour')).toBeInTheDocument();
  });

  test('clicking Add to Bag without selecting a size makes ZimmSizeSelector show its error state', async () => {
    // Arrange
    // No controlledVariationValues and localSizeValue starts as null → effectiveSizeValue=null.
    // handleAddToBag detects hasSizeAttribute=true and !effectiveSizeValue → setHasAddToBagError(true),
    // which flows into ZimmSizeSelector as showError=true.
    mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

    render(
      <ProductView product={buildProductWithSize()} addToCart={vi.fn()} showActionButtons={false} {...quietProps} />,
    );

    const sizeSelector = screen.getByTestId('zimm-size-selector');
    const button = screen.getByTestId('zimm-add-to-bag');

    // Assert initial state — no error yet
    expect(sizeSelector).toHaveAttribute('data-show-error', 'false');

    // Act
    await userEvent.click(button);

    // Assert — showError prop is now true after the failed attempt
    expect(screen.getByTestId('zimm-size-selector')).toHaveAttribute('data-show-error', 'true');
  });

  test('shows colour prompt in errorContainerRef for a colour-only product with no size attribute', async () => {
    // Colour-only product — no size branch renders, so the inline alert inside the size branch
    // never mounts. The colour alert must fall back to the errorContainerRef box.
    // showActionButtons=true is required: renderActionButtons() is the only path that renders
    // Add to Bag when there is no size attribute, and it is gated by showActionButtons.
    // Both the desktop box and the sticky mobile bar call renderActionButtons(), so
    // getAllByTestId finds two matches — click the first.
    mockDerivedProduct({
      variationAttributes: [derivedColourAttr],
      variationParams: {}, // colour absent → isColourMissing=true
      variant: null,
    });

    render(
      <ProductView
        product={{
          id: 'colour-only',
          name: 'Colour Only Product',
          type: { item: true },
          currency: 'AUD',
          inventory: { orderable: true, backorderable: false },
          variationAttributes: [{ id: 'color', values: [{ value: 'ivory', orderable: true }] }],
          imageGroups: [],
        }}
        addToCart={vi.fn()}
        showActionButtons={true}
        {...quietProps}
      />,
    );

    const [addToBagBtn] = screen.getAllByTestId('zimm-add-to-bag');
    await userEvent.click(addToBagBtn);

    expect(screen.queryByTestId('zimm-size-selector')).not.toBeInTheDocument();
    expect(screen.getByText('Please select a colour')).toBeInTheDocument();
  });

  describe('SFCC-315 — Add to Bag opens the cart drawer, not the base AddToCartModal', () => {
    test('opens the cart drawer with the real clicked button as the AC10 focus-return trigger — the PDP add-to-bag trigger origin', async () => {
      const onCartDrawerOpen = vi.fn();
      mockUseCartDrawer.mockReturnValue({
        isOpen: false,
        onOpen: onCartDrawerOpen,
        onClose: vi.fn(),
        triggerRef: { current: null },
      });
      mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

      render(
        <ProductView
          product={buildProductWithSize()}
          addToCart={vi.fn().mockResolvedValue([{ itemId: 'sku-s' }])}
          controlledVariationValues={{ size: 'S' }}
          validateOrderability={() => true}
          showActionButtons={false}
          {...quietProps}
        />,
      );

      const button = screen.getByTestId('zimm-add-to-bag');
      await userEvent.click(button);

      // The real button itself — not a wrapper, not document.activeElement — is what AC10 must
      // return focus to. See addToBagTriggerRef's own comment in index.tsx for the mechanism
      // (wrapping Box ref + querySelector, since ZimmButton's onClick carries no event and
      // ZimmButton isn't forwardRef).
      await waitFor(() => {
        expect(onCartDrawerOpen).toHaveBeenCalledWith(button);
      });
    });

    test('does not open the cart drawer when addToCart resolves with no items added', async () => {
      const onCartDrawerOpen = vi.fn();
      mockUseCartDrawer.mockReturnValue({
        isOpen: false,
        onOpen: onCartDrawerOpen,
        onClose: vi.fn(),
        triggerRef: { current: null },
      });
      mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

      render(
        <ProductView
          product={buildProductWithSize()}
          addToCart={vi.fn().mockResolvedValue(null)}
          controlledVariationValues={{ size: 'S' }}
          validateOrderability={() => true}
          showActionButtons={false}
          {...quietProps}
        />,
      );

      await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

      expect(onCartDrawerOpen).not.toHaveBeenCalled();
    });

    test('does not open the cart drawer, and shows an error toast, when addToCart rejects', async () => {
      const onCartDrawerOpen = vi.fn();
      const showToast = vi.fn();
      mockUseCartDrawer.mockReturnValue({
        isOpen: false,
        onOpen: onCartDrawerOpen,
        onClose: vi.fn(),
        triggerRef: { current: null },
      });
      mockUseToast.mockReturnValueOnce(showToast);
      mockDerivedProduct({ variationAttributes: [derivedSizeAttr] });

      render(
        <ProductView
          product={buildProductWithSize()}
          addToCart={vi.fn().mockRejectedValue(new Error('network error'))}
          controlledVariationValues={{ size: 'S' }}
          validateOrderability={() => true}
          showActionButtons={false}
          {...quietProps}
        />,
      );

      await userEvent.click(screen.getByTestId('zimm-add-to-bag'));

      await waitFor(() => {
        expect(showToast).toHaveBeenCalledWith(expect.objectContaining({ status: 'error' }));
      });
      expect(onCartDrawerOpen).not.toHaveBeenCalled();
    });
