    });

    test('disables the toggle when the product has no resolvable id, even though a callback exists', () => {
      // No `id`/`productId` on the product, and mockDerivedProduct()'s default variant is null —
      // wishlistProductId resolves to undefined, so the toggle must stay disabled regardless of
