file.content:
              {/*
                                Customize the skeletons shown for attributes to suit your needs. At the point
                                that we show the skeleton we do not know how many variations are selectable. So choose
                                a a skeleton that will meet most of your needs.
                            */}
              {showLoading ? (
                <>
                  {/* First Attribute Skeleton */}
                  <Skeleton height={6} width={32} />
                  <Skeleton height={20} width={64} />

                  {/* Second Attribute Skeleton */}
                  <Skeleton height={6} width={32} />
                  <Skeleton height={20} width={64} />
                </>
              ) : (
                variationAttributes.map((attr: SfccVariationAttribute) => {
                  const { id, name, selectedValue, values } = attr;

                  // renderVariationAttribute lets callers (e.g. the PDP) override how a specific
                  // variation attribute is displayed — the PDP injects ZimmColourSwatchGroup here.
                  // Returning undefined (not null) falls through to the base SwatchGroup below.
                  const custom = renderVariationAttribute?.(attr);
                  if (custom !== undefined) return <React.Fragment key={id}>{custom}</React.Fragment>;

                  // Size attribute — render the Zimmermann size selector dropdown, then
                  // Add to Bag immediately below (no gap). The button is suppressed from the
                  // desktop renderActionButtons() box below to avoid rendering it twice.
                  if (id === SFCC_SIZE_ATTRIBUTE_ID) {
                    const sizeValues = values.map((v) => ({
                      value: v.value ?? '',
                      name: v.name,
                      orderable: v.orderable ?? false,
                    }));
                    return (
                      // Outer Box groups size selector + ATB + error + footerLinks into one
                      // VStack child so the inner VStack's spacing="var(--zimm-scale-700)"
                      // does not create a gap between ATB and the content below it (SFCC-737).
                      // gap="var(--zimm-scale-400)" sets the 16px space between the
                      // [size selector + ATB + error] group and footerLinks.
                      <Box
                        key={id}
                        display="flex"
                        flexDirection="column"
                        gap={addToCart && !updateCart && footerLinks ? 'var(--zimm-scale-400)' : undefined}
                      >
                        {/* [size selector + ATB + error] — tight group, no gap between them */}
                        <Box display="flex" flexDirection="column">
                          <Box display="flex" flexDirection="column" gap="var(--zimm-scale-700)">
                            <Box display="flex" flexDirection="column">
                              <ZimmSizeSelector
                                ref={sizeSelectorRef}
                                variationAttribute={{ id, name: name ?? '', values: sizeValues }}
                                selectedValue={effectiveSizeValue}
                                isBackorderable={product?.inventory?.backorderable ?? false}
                                onSelectionChange={(value: string) => {
                                  setLocalSizeValue(value);
                                  onVariationChange?.(id, value);
                                  setHasSizeRequiredError(false);
                                }}
                                showError={hasSizeRequiredError || isMaxOrderQtyReached}
                                errorMessage={
                                  isMaxOrderQtyReached ? intl.formatMessage(MAX_ORDER_QTY_MESSAGE) : undefined
                                }
                                onFindYourSizeClick={onFindYourSizeClick}
                                onSizeGuideClick={onSizeGuideClick}
                              />
                              {showOptionsMessage && isColourMissing && (
                                <Text
                                  role="alert"
                                  sx={{
                                    marginTop: 'var(--zimm-scale-2xs)',
                                    fontFamily: 'var(--zimm-font-family-body)',
                                    fontSize: 'var(--zimm-font-size-3xs)',
                                    fontWeight: 'var(--zimm-font-weight-regular)',
                                    lineHeight: 'var(--zimm-font-lineheight-2xs)',
                                    color: 'var(--zimm-color-status-error)',
                                  }}
                                >
                                  {intl.formatMessage(COLOUR_REQUIRED_MESSAGE)}
                                </Text>
                              )}
                            </Box>
                            {/* Add to Bag is only for the addToCart flow — updateCart uses the
                                base renderActionButtons() Update button shown below. */}
                            {addToCart && !updateCart && (
                              <Box
                                ref={addToBagTriggerRef}
                                display="flex"
                                flexDirection="column"
                                gap="var(--zimm-scale-2xs)"
                              >
                                <ZimmButton
                                  label={intl.formatMessage(ADD_TO_BAG_MESSAGE)}
                                  variant="primary"
                                  fullWidth={true}
                                  disabled={isBasketLoading || disableButton}
                                  ariaDisabled={
                                    (hasSizeAttribute && hasSizeRequiredError && !effectiveSizeValue) ||
                                    isSelectedSizeOOS ||
                                    isMaxOrderQtyReached
                                  }
                                  ariaDescribedBy={isMaxOrderQtyReached ? `zimm-size-selector-${id}-error` : undefined}
                                  onClick={() => {
                                    void handleAddToBag();
                                  }}
                                />
                              </Box>
                            )}
                          </Box>
                          {/* "Select all options" error for size products — placed here (inside the
                              same VStack child as ATB) so the inner VStack spacing does not add
                              a gap between ATB and this message. The colour-missing variant is
                              handled inline above the size selector. */}
                          <Box ref={errorContainerRef}>
                            {!showLoading && showOptionsMessage && !isColourMissing && (
                              <Fade in={true}>
                                <Text color="var(--zimm-color-status-error)" fontWeight={600} marginBottom={8}>
                                  {intl.formatMessage({
                                    defaultMessage: 'Please select all your options above',
                                    id: 'product_view.label.select_all_options',
                                  })}
                                </Text>
                              </Fade>
                            )}
                          </Box>
                        </Box>
                        {/* footerLinks (e.g. "Find in Boutique") — second flex child of the outer
                            Box; the outer Box's gap="var(--zimm-scale-400)" creates the 16px space
                            between ATB and this link. Suppressed from the delivery Box below. */}
                        {addToCart && !updateCart && footerLinks}
                      </Box>
                    );
                  }

                  // All other attributes (colour, etc.) — keep existing SwatchGroup/Swatch rendering unchanged.
                  const swatches = values.map(
                    ({ href, name, image, value, orderable }: SfccVariationValue, index: number) => {
                      // audit-allow: verbatim from base product-view (index.jsx:689); copy-first requires it unchanged
                      const content = image ? (
                        <Box
                          height="100%"
                          width="100%"
                          minWidth="32px"
                          backgroundRepeat="no-repeat"
                          backgroundSize="cover"
                          backgroundColor={name.toLowerCase()}
                          backgroundImage={`url(${image.disBaseLink || image.link})`}
                        />
                      ) : (
                        name
                      );
                      const hasSelection = Boolean(selectedValue?.value);
                      const isSelected = selectedValue?.value === value;
                      const isFirst = index === 0;
                      // To mimic the behavior of a native radio input, only
                      // one swatch should receive tab focus; the rest can be
                      // selected using arrow keys when the swatch group has
                      // focus. The focused element is the selected option or
                      // the first in the group, if no option is selected.
                      // This is a slight difference, for simplicity, from the
                      // native element, where the first element is focused on
                      // `Tab` and the _last_ element is focused on `Shift+Tab`
                      const isFocusable = isSelected || (!hasSelection && isFirst);
                      return (
                        <Swatch
                          key={value}
                          href={href}
                          disabled={!orderable}
                          value={value}
                          name={name}
                          variant={id === SFCC_COLOUR_ATTRIBUTE_ID ? 'circle' : 'square'}
                          selected={isSelected}
                          isFocusable={isFocusable}
                        >
                          {content}
                        </Swatch>
                      );
                    },
                  );
                  return (
                    <SwatchGroup
                      key={id}
                      value={selectedValue?.value}
                      displayName={selectedValue?.name || ''}
                      label={intl.formatMessage(
                        {
                          defaultMessage: '{variantType}',
                          id: 'product_view.label.variant_type',
                        },
                        { variantType: name },
                      )}
                      handleChange={onVariationChange ? (value: string) => onVariationChange(id, value) : undefined}
                    >
                      {swatches}
                    </SwatchGroup>
                  );
                })
              )}

              {/* audit-allow: verbatim from base product-view (index.jsx:754); copy-first requires it unchanged */}
              {showQuantityPicker && !isProductASet && !isProductPartOfBundle && !hasSizeAttribute && (
                <VStack align="stretch" maxWidth={'200px'}>
                  <Box fontWeight="bold">
                    <label htmlFor="quantity">
                      {intl.formatMessage({
                        defaultMessage: 'Quantity',
                        id: 'product_view.label.quantity',
                      })}
                      :
                    </label>
                  </Box>

                  <QuantityPicker
                    id="quantity"
                    step={stepQuantity}
                    value={quantity}
                    min={minOrderQuantity}
                    {...(maxOrderQuantity != null && { max: maxOrderQuantity })}
                    onChange={(stringValue: string, numberValue: number) => {
                      // Set the Quantity of product to value of input if value number
                      if (numberValue >= 0) {
                        setQuantity(numberValue);
                        if (isProductABundle) setSelectedBundleQuantity(numberValue);
                      } else if (stringValue === '') {
                        // We want to allow the use to clear the input to start a new input so here we set the quantity to '' so NAN is not displayed
                        // User will not be able to add '' qauntity to the cart due to the add to cart button enablement rules
                        setQuantity(stringValue);
                      }
                    }}
                    onBlur={(e: React.FocusEvent<HTMLInputElement>) => {
                      // Default to 1the `minOrderQuantity` if a user leaves the box with an invalid value
                      const value = e.target.value;
                      if (parseInt(value) < 0 || value === '') {
                        setQuantity(minOrderQuantity);
                        if (isProductABundle) setSelectedBundleQuantity(minOrderQuantity);
                      }
                    }}
                    onFocus={(e: React.FocusEvent<HTMLInputElement>) => {
                      // This is useful for mobile devices, this allows the user to pop open the keyboard and set the
                      // new quantity with one click. NOTE: This is something that can be refactored into the parent
                      // component, potentially as a prop called `selectInputOnFocus`.
                      e.target.select();
                    }}
                    productName={product?.name}
                  />
                </VStack>
              )}
              {/* For size products, the error Box is rendered inside the size attribute case above
                  (co-located with ATB) so the inner VStack spacing does not add a gap between
                  ATB and the message. Only render here for non-size products. */}
              {!hasSizeAttribute && (
                <Box ref={errorContainerRef}>
                  {/* Colour-only products (no size branch renders) need the colour alert here. */}
                  {!showLoading && showOptionsMessage && isColourMissing && (
                    <Fade in={true}>
                      <Text
                        role="alert"
                        sx={{
                          fontFamily: 'var(--zimm-font-family-body)',
                          fontSize: 'var(--zimm-font-size-3xs)',
                          fontWeight: 'var(--zimm-font-weight-regular)',
                          lineHeight: 'var(--zimm-font-lineheight-2xs)',
                          color: 'var(--zimm-color-status-error)',
                        }}
                      >
                        {intl.formatMessage(COLOUR_REQUIRED_MESSAGE)}
                      </Text>
                    </Fade>
                  )}
                  {!showLoading && showOptionsMessage && !isColourMissing && (
                    <Fade in={true}>
                      <Text color="var(--zimm-color-status-error)" fontWeight={600} marginBottom={8}>
                        {intl.formatMessage({
                          defaultMessage: 'Please select all your options above',
                          id: 'product_view.label.select_all_options',
                        })}
                      </Text>
                    </Fade>
                  )}
                </Box>
              )}
              <HideOnDesktop>
                {showFullLink && product && (
                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
                  </Link>
                )}
              </HideOnDesktop>
              {isProductASet && <p>{product?.shortDescription}</p>}
            </VStack>

            <Box>
              {showStockMessage && !showLoading && showInventoryMessage && !customInventoryMessage && (
                <Fade in={true}>
                  <Text color="var(--zimm-color-status-error)" fontWeight={600} marginBottom={8}>
                    {inventoryMessage}
                  </Text>
                </Fade>
              )}
              {showStockMessage && !showLoading && customInventoryMessage && (
                <Fade in={true}>
                  <Text color="var(--zimm-color-status-error)" fontWeight={600} marginBottom={8}>
                    {customInventoryMessage}
                  </Text>
                </Fade>
              )}
              <Box>
                {showDeliveryOptions && (
                  <>
                    <Box mb={4}>
                      <Text fontWeight={600} mb={3}>
                        <FormattedMessage defaultMessage="Delivery:" id="product_view.label.delivery" />
                      </Text>
                      <RadioGroup
                        value={pickupInStore ? DELIVERY_OPTIONS.PICKUP : DELIVERY_OPTIONS.DELIVERY}
                        onChange={handleDeliveryOptionChange}
                        mb={1}
                      >
                        <Stack direction="column" spacing={2}>
                          <Radio value={DELIVERY_OPTIONS.DELIVERY} isDisabled={disableButton}>
                            <FormattedMessage
                              defaultMessage="Ship to Address"
                              id="product_view.label.ship_to_address"
                            />
                          </Radio>
                          {storeLocatorEnabled && (
                            <Radio
                              value={DELIVERY_OPTIONS.PICKUP}
                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
                            >
                              <FormattedMessage
                                defaultMessage="Pick Up in Store"
                                id="product_view.label.pickup_in_store"
                              />
                            </Radio>
                          )}
                        </Stack>
                      </RadioGroup>
                    </Box>

                    {storeLocatorEnabled && (
                      <>
                        {storeName && inventoryId && (
                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
                            {!isSelectedStoreOutOfStock
                              ? intl.formatMessage(
                                  {
                                    id: 'product_view.status.in_stock_at_store',
                                    defaultMessage: 'In stock at {storeName}',
                                  },
                                  {
                                    storeName: (
                                      <Link
                                        as="button"
                                        color="blue.600"
                                        textDecoration="underline"
                                        onClick={onOpenStoreLocator}
                                      >
                                        {storeName}
                                      </Link>
                                    ),
                                  },
                                )
                              : intl.formatMessage(
                                  {
                                    id: 'product_view.status.out_of_stock_at_store',
                                    defaultMessage: 'Out of Stock at {storeName}',
                                  },
                                  {
                                    storeName: (
                                      <Link
                                        as="button"
                                        color="blue.600"
                                        textDecoration="underline"
                                        onClick={onOpenStoreLocator}
                                      >
                                        {storeName}
                                      </Link>
                                    ),
                                  },
                                )}
                          </Text>
                        )}

                        {/* Show label if pickup is disabled due to no store/inventoryId */}
                        {!pickupEnabled && !storeName && !inventoryId && (
                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
                            <FormattedMessage
                              defaultMessage="Pick up in "
                              id="product_view.label.pickup_in_select_store_prefix"
                            />{' '}
                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
                              <FormattedMessage
                                defaultMessage="Select Store"
                                id="product_view.label.select_store_link"
                              />
                            </Link>
                          </Text>
                        )}
                      </>
                    )}
                  </>
                )}
                {/* Add to Bag is rendered immediately below ZimmSizeSelector when a size
                    attribute is present — suppress it here to avoid a duplicate on desktop.
                    showActionButtons=false (PDP) hides this entirely; Add to Bag is inline. */}
                {/* Suppress only for addToCart + size products (button is inline above).
                    When updateCart is present, renderActionButtons() holds the Update button. */}
                {showActionButtons && (
                  <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
                    {renderActionButtons()}
                  </Box>
                )}
                {/* Suppressed for size+addToCart products — rendered inside the size
                    attribute Box above with a var(--zimm-scale-400) gap from ATB. */}
                {!(hasSizeAttribute && addToCart && !updateCart) && footerLinks}
              </Box>
            </Box>
          </VStack>
        </Flex>

        {/* Sticky call-to-action buttons for mobile and certain product types.
            showActionButtons=false (PDP with size attribute) omits this entirely.
            renderActionButtons() already skips Add to Bag for sized products, so
            wishlist, express, and custom CTAs still appear here when present. */}
        {showActionButtons && (
          <Box
            position="fixed"
            bg="var(--zimm-color-bg-07)"
            width="100%"
            display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
            p={[4, 4, 6]}
            left={0}
            bottom={0}
            zIndex={2}
            boxShadow={theme.shadows.top}
          >
            {renderActionButtons()}
          </Box>
        )}

        {/* Loading overlay during express payment confirmation */}
        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
      </Flex>
    );
  },
);

ProductView.displayName = 'ProductView';

/*
 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
 * same prop contract, and do so at compile time for every caller rather than as a dev-only
 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
 */

export default ProductView;

