    >
      {label}
    </button>
  ),
}));

const mockUseDerivedProduct = vi.mocked(useDerivedProduct);
const mockUseCartDrawer = vi.mocked(useCartDrawer);

function mockDerivedProduct(overrides: Record<string, unknown> = {}) {
  mockUseDerivedProduct.mockReturnValue({
    showLoading: false,
    showInventoryMessage: false,
    inventoryMessage: '',
    quantity: 1,
    minOrderQuantity: 1,
    setQuantity: vi.fn(),
    variant: null,
    variationParams: {},
    variationAttributes: [],
    stockLevel: 10,
    stepQuantity: 1,
    isOutOfStock: false,
    unfulfillable: false,
    isSelectedStoreOutOfStock: false,
    selectedStore: null,
    ...overrides,
  });
}

window.HTMLElement.prototype.scrollIntoView = vi.fn();

const simpleProduct = {
  id: 'test-jacket',
  name: 'Test Jacket',
  type: { item: true },
  currency: 'AUD',
  inventory: { orderable: true, backorderable: false },
  variationAttributes: [],
  imageGroups: [],
};

const quietProps = {
  showImageGallery: false,
  showDeliveryOptions: false,
  showQuantityPicker: false,
} as const;

describe('SCRATCH — SFCC-11 call site 3: updateCart / "Update" button drives handleCartItem', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockDerivedProduct();
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: vi.fn(),
      onClose: vi.fn(),
      triggerRef: { current: null },
    });
  });

  test('clicking the real "Update" button calls updateCart, but does NOT call onCartDrawerOpen (dead-code check on handleCartItem)', async () => {
    const onCartDrawerOpen = vi.fn();
    mockUseCartDrawer.mockReturnValue({
      isOpen: false,
      onOpen: onCartDrawerOpen,
      onClose: vi.fn(),
      triggerRef: { current: null },
    });
    const updateCart = vi.fn().mockResolvedValue({ itemId: 'sku-s' });

    render(
      <ProductView
        product={simpleProduct}
        updateCart={updateCart}
        validateOrderability={() => true}
        {...quietProps}
      />,
    );

    // showActionButtons defaults to true (must NOT pass showActionButtons={false} — that would
    // suppress renderActionButtons() entirely and the Update button would never render at all).
    // Both the desktop box and the sticky mobile bar call renderActionButtons(), so two matches.
    const updateButtons = screen.getAllByRole('button', { name: 'Update' });
    expect(updateButtons.length).toBeGreaterThan(0);
    const [updateButton] = updateButtons;

    await userEvent.click(updateButton);

    // Sanity anchor (the "prove, don't assert" check): if this fails, the harness/click wiring
    // is broken, not the production code — updateCart really was reached.
    await waitFor(() => {
      expect(updateCart).toHaveBeenCalledTimes(1);
    });
    expect(updateCart).toHaveBeenCalledWith(simpleProduct, 1);

    // THE FINDING: handleCartItem's `if (updateCart) { await updateCart(...); return; }` guard
    // returns before ever reaching the addToCart branch that calls onCartDrawerOpen — so the
    // real, reachable "Update" click path never opens the cart drawer at all. This is identical
    // to the pristine base SFCC file's own handleCartItem (confirmed by reading
    // node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx lines
    // 388-415) — i.e. not a regression this diff introduced, but the diff's own
    // `onCartDrawerOpen(e?.currentTarget ?? null)` addition sits inside a branch that was
    // already unreachable given this override's `if (updateCart) {...} else if
    // (!hasSizeAttribute) {...}` button-render restructuring (pre-existing, unchanged by this
    // diff — confirmed via `git diff HEAD` showing those lines as unchanged context).
    expect(onCartDrawerOpen).not.toHaveBeenCalled();
  });
});

