1	/*
2	 * THROWAWAY scratch test — NOT part of the repo, deleted after use.
3	 * Purpose: drive the real `updateCart` / "Update" button code path (the THIRD cart-drawer
4	 * call site) in overrides/app/components/product-view/index.tsx, which
5	 * overrides/app/components/product-view/index.test.tsx has zero coverage for (confirmed by
6	 * grep — no "handleCartItem"/"updateCart"/"cart-button"/"Update" match in that file).
7	 *
8	 * Mocks copied verbatim from the real index.test.tsx (same repo, same commit), with exactly
9	 * two mock targets rewritten from a relative specifier to the equivalent `app/...` alias form
10	 * (see comments below at those two mocks) because this file does not live in
11	 * overrides/app/components/product-view/ the way the real test file does, so a relative
12	 * specifier here would resolve to the wrong (non-existent) location. Every other mock target is
13	 * either a bare package specifier or already alias-based, so it resolves identically regardless
14	 * of this file's location.
15	 */
16	
17	import React from 'react';
18	import { describe, test, expect, vi, beforeEach } from 'vitest';
19	import { render, screen, waitFor } from '@testing-library/react';
20	import userEvent from '@testing-library/user-event';
21	import ProductView from 'app/components/product-view';
22	import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
23	import { useCartDrawer } from 'app/hooks/useCartDrawer';
24	
25	vi.mock('react-router-dom', () => ({
26	  useLocation: vi.fn(() => ({ search: '', pathname: '/product/test-product' })),
27	}));
28	
29	vi.mock('react-intl', async (importOriginal) => {
30	  const actual = await importOriginal<typeof import('react-intl')>();
31	  return {
32	    ...actual,
33	    useIntl: vi.fn(() => ({
34	      formatMessage: (msg: { defaultMessage?: string }) => msg.defaultMessage ?? '',
35	    })),
36	    FormattedMessage: ({ defaultMessage }: { defaultMessage: string }) => <>{defaultMessage}</>,
37	  };
38	});
39	
40	vi.mock('@salesforce/retail-react-app/app/components/shared/ui', () => ({
41	  Flex: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
42	  Box: React.forwardRef<HTMLDivElement, React.PropsWithChildren>(function Box({ children }, ref) {
43	    return <div ref={ref}>{children}</div>;
44	  }),
45	  VStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
46	  HStack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
47	  Heading: ({ children }: React.PropsWithChildren) => <h2>{children}</h2>,
48	  // Real Chakra Button IS forwardRef and forwards the real click SyntheticEvent through an
49	  // unwrapped `onClick={handleCartItem}` reference — this mock only needs to match that one
50	  // real capability (forwarding the real event) to make e?.currentTarget testable.
51	  Button: ({
52	    children,
53	    onClick,
54	    disabled,
55	    isLoading,
56	  }: React.PropsWithChildren<{
57	    onClick?: React.MouseEventHandler;
58	    disabled?: boolean;
59	    isLoading?: boolean;
60	  }>) => (
61	    <button onClick={onClick} disabled={disabled ?? isLoading}>
62	      {children}
63	    </button>
64	  ),
65	  Skeleton: ({ children }: React.PropsWithChildren) => <>{children}</>,
66	  Text: ({ children }: React.PropsWithChildren) => <span>{children}</span>,
67	  Fade: ({ children }: React.PropsWithChildren) => <>{children}</>,
68	  Stack: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
69	  Radio: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
70	  RadioGroup: ({ children }: React.PropsWithChildren) => <div>{children}</div>,
71	  useTheme: vi.fn(() => ({ shadows: { top: 'none' } })),
72	}));
73	
74	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
75	  useCurrency: vi.fn(() => ({ currency: 'AUD' })),
76	  useDerivedProduct: vi.fn(),
77	}));
78	
79	vi.mock('app/hooks/useSafeHref', () => ({
80	  useSafeHref: () => (href: string) => href,
81	}));
82	
83	vi.mock('app/hooks/useCartDrawer', () => ({
84	  useCartDrawer: vi.fn(),
85	}));
86	
87	vi.mock('@salesforce/retail-react-app/app/constants', () => ({
88	  STORE_LOCATOR_IS_ENABLED: false,
89	  API_ERROR_MESSAGE: { defaultMessage: 'An error occurred.', id: 'app.error.api' },
90	}));
91	
92	vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
93	  getConfig: vi.fn(() => null),
94	}));
95	
96	vi.mock('@salesforce/commerce-sdk-react', () => ({
97	  useShopperBasketsV2Mutation: vi.fn(() => ({ mutateAsync: vi.fn() })),
98	}));
99	
100	vi.mock('@salesforce/retail-react-app/app/hooks/use-sf-payments', () => ({
101	  useSFPayments: vi.fn(() => ({ confirmingBasket: false })),
102	  useExpressCheckoutEnabled: vi.fn(() => ({ pdp: false })),
103	  EXPRESS_BUY_NOW: 'EXPRESS_BUY_NOW',
104	}));
105	
106	vi.mock('@salesforce/retail-react-app/app/components/image-gallery', () => ({
107	  default: () => <div data-testid="image-gallery" />,
108	  Skeleton: () => <div data-testid="image-gallery-skeleton" />,
109	}));
110	
111	// REWRITTEN from the real file's relative './ui-kits/organisms/zimmProductGallery' — this file
112	// does not live beside index.tsx, so the relative specifier would resolve to a non-existent
